end

function Slider:Set(value, silent)
	if type(value) ~= "number" then
		return
	end
	value = self:_snap(value)
	if value == self.Value then
		return
	end
	self.Value = value
	self:_render(not self._dragging)
	if not silent then
		self:_emit(value)
	end
end

return Slider
end
